#!/usr/bin/env node
// Read-only, cross-repository signing prerequisite. No generated bytes are
// accepted on faith: compare the shipped Swift capsule and every guard command.
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { gateCBootstrapAdmissionCommand, GATE_C_BOOTSTRAP_REPLACEMENT_CAPSULE_SHA256,
  GATE_C_BOOTSTRAP_REPLACEMENT_FAILURE_CODES } from '../src/lib/sonuvi-gate-c-bootstrap-replacement-contract.mjs';

const ios = process.argv[2];
assert.ok(ios && process.argv.length === 3, 'usage: node scripts/verify-ios-bootstrap-contract.mjs <iOS-worktree>');
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const swift = path.join(ios, 'Sources/NowPlayingCarPlayCore');
const capsule = await fs.readFile(path.join(root, 'scripts/sonuvi-sftp-bootstrap-activate-v2.sh'));
const embedded = await fs.readFile(path.join(swift, 'SonuviGateCExistingInstallUpgradeBootstrapActivation.swift'), 'utf8');
const encoded = embedded.split('private static let encodedCapsule = [')[1]?.split('].joined()')[0];
assert.ok(encoded, 'missing embedded capsule');
const bytes = Buffer.from([...encoded.matchAll(/"([A-Za-z0-9+/=]+)"/g)].map(match => match[1]).join(''), 'base64');
assert.deepEqual(bytes, capsule, 'iOS capsule differs from reviewed executable source');
const sha256 = crypto.createHash('sha256').update(capsule).digest('hex');
assert.equal(sha256, GATE_C_BOOTSTRAP_REPLACEMENT_CAPSULE_SHA256);
assert.ok(embedded.includes(`static let capsuleSHA256 = "${sha256}"`));
const contract = await fs.readFile(path.join(swift, 'SonuviGateCBootstrapReviewedContract.swift'), 'utf8');
for (const operation of ['stageRelease', 'activateExisting', 'recoverExisting']) {
  const literal = contract.split(`static let ${operation} = `)[1]?.split('\n')[0];
  assert.equal(JSON.parse(literal), gateCBootstrapAdmissionCommand(operation), `${operation} omits or changes the reviewed guard`);
}
const codes = contract.split('static let failureCodes: Set<String> = [')[1]?.split(']')[0];
assert.deepEqual([...codes.matchAll(/"([a-z_]+)"/g)].map(match => match[1]), GATE_C_BOOTSTRAP_REPLACEMENT_FAILURE_CODES);
console.log(JSON.stringify({ ok: true, capsuleSHA256: sha256, capsuleBytes: capsule.length, guardedCommands: 3, typedFailureCodes: GATE_C_BOOTSTRAP_REPLACEMENT_FAILURE_CODES.length }));
